#include <cstdio>
#include <vector>
#include <algorithm>
using namespace std;
int main(){int n;if(scanf("%d",&n)!=1)return 0;vector<long long>a(n+1);for(int i=1;i<=n;i++)scanf("%lld",&a[i]);
vector<int>dp(n+1,0);
for(int i=1;i<=n;i++){dp[i]=dp[i-1]+a[i]*i;if(i>=2)dp[i]=max<long long>(dp[i],dp[i-2]+a[i]*(i-1)+a[i-1]*i);}
printf("%d\n",dp[n]);}

